<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { AlbumDraftSchema,CreationDraftSchema,FitnessEntryDraftSchema,PlaylistDraftSchema,type AlbumDraft,type CreationDraft,type FitnessEntryDraft,type PlaylistDraft } from '@xvyin/contracts';
import { ApiError, dateTime, type Collection, type DraftRecord } from '../api';
import { AUTOSAVE_DELAY, acknowledgeSnapshot, exportDraft, listRecovery, removeCapturedRecovery, removeRecovery, snapshotString, writeRecovery, type EditorSnapshot, type RecoveryRecord, type RecoverySource } from '../draft-recovery';
import RevisionHistory from './RevisionHistory.vue';
import { providerContentId } from '../provider-input';
import DraftPreview from './DraftPreview.vue';import { externalMediaLink } from '../media';
import BlockEditor from './BlockEditor.vue';import PhotoEditor from './PhotoEditor.vue';import AssetField from './AssetField.vue';
type Editable=CreationDraft|AlbumDraft|FitnessEntryDraft|PlaylistDraft;
const props=defineProps<{collection:Collection;record:DraftRecord<Editable>|null;busy:boolean;owner:string;authenticated:boolean;recoverySource?:RecoverySource}>();
type SaveDone=(record?:DraftRecord<Editable>,error?:unknown)=>RecoverySource|void;
const emit=defineEmits<{save:[draft:Editable,publish:boolean,done:SaveDone];cancel:[];dirty:[value:boolean];restored:[record:DraftRecord<Editable>];restoreBusy:[value:boolean]}>();
const defaults:Record<Collection,()=>Editable>={
creations:()=>CreationDraftSchema.parse({kind:'mixed',title:'',slug:'',sortOrder:0}),
albums:()=>AlbumDraftSchema.parse({title:'',slug:'',sortOrder:0}),
fitness:()=>({entryDate:'',title:'',caption:'',tags:[],sortOrder:0,featured:false,photos:[]}),
playlists:()=>({name:'',source:'local',sourceId:null,sortOrder:0,enabled:true,isDefault:false,tracks:[]}),
};
const previewOpen=ref(false);
const draft=ref<Editable>(JSON.parse(JSON.stringify(props.record?.draft??defaults[props.collection]())));
const creation=computed(()=>draft.value as CreationDraft);const album=computed(()=>draft.value as AlbumDraft);const fitness=computed(()=>draft.value as FitnessEntryDraft);const playlist=computed(()=>draft.value as PlaylistDraft);
const tagText=ref(props.collection==='creations'?creation.value.tags.join('，'):props.collection==='fitness'?fitness.value.tags.join('，'):'');const sourceText=ref(props.collection==='creations'?creation.value.sourceLinks.join('\n'):'');const issues=ref<string[]>([]);
const dirty = ref(false), historyOpen = ref(false), historyRestoring = ref(false), localIssue = ref(''), saveStatus = ref(''), paused = ref(false), recovery = ref<RecoveryRecord[]>([]), composing = ref(false), staleRecovery = ref(false);
let restoreStamp = '';
const pendingRemoval:RecoveryRecord[]=[];
let disposed = false, applying = false, timer: ReturnType<typeof setTimeout> | undefined, baseVersion = props.record?.version || 0, entryId = props.record?.id || 'new';
// Each mounted editor owns its own recovery slot. Tabs never delete or overwrite
// each other's pending work; a reload discovers all matching slots explicitly.
const tabId = crypto.randomUUID();
function snapshot():EditorSnapshot { return JSON.parse(JSON.stringify({draft:draft.value,tagText:tagText.value,sourceText:sourceText.value})); }
let baseline = snapshotString(snapshot());
function recoveryRecord():RecoveryRecord { return {schemaVersion:1,owner:props.owner,collection:props.collection,entryId,tabId,baseVersion,updatedAt:Date.now(),snapshot:snapshot()}; }
function persistLocal() { if (!dirty.value || recovery.value.length || !props.owner || !props.authenticated) return false; try { writeRecovery(localStorage,recoveryRecord());for(const item of pendingRemoval.splice(0))if(item.entryId!==entryId||item.tabId!==tabId)removeRecovery(localStorage,item);localIssue.value='';return true; } catch {localIssue.value='浏览器未能保存本机恢复副本，请导出草稿并手动保存。';return false;} }
function removeOwnRecovery() {try {removeRecovery(localStorage,recoveryRecord());for(const item of pendingRemoval.splice(0))removeRecovery(localStorage,item);} catch {localIssue.value='本机恢复副本暂时无法清理。';}}
try { const own=listRecovery(localStorage,props.owner,props.collection,entryId);const source=props.recoverySource?.entryId==='new'?listRecovery(localStorage,props.owner,props.collection,'new').filter(item=>item.tabId===props.recoverySource!.tabId):[];recovery.value=[...new Map([...own,...source].map(item=>[`${item.entryId}/${item.tabId}`,item])).values()].filter(item=>snapshotString(item.snapshot)!==baseline); } catch {localIssue.value='浏览器不允许读取本机恢复记录。';}
function schedule() { if(timer)clearTimeout(timer);if(disposed||!dirty.value||paused.value||recovery.value.length||!props.record||!props.authenticated||historyRestoring.value)return;timer=setTimeout(()=>{if(composing.value||props.busy){schedule();return;}save(false,true);},AUTOSAVE_DELAY); }
function changed() {if(applying)return;dirty.value=snapshotString(snapshot())!==baseline;emit('dirty',dirty.value);persistLocal();schedule();}
watch([draft,tagText,sourceText],changed,{deep:true,flush:'sync'});
watch(()=>props.authenticated,value=>{if(value)schedule();else if(timer)clearTimeout(timer);});
function restoreLocal(item:RecoveryRecord) { applying=true;draft.value=JSON.parse(JSON.stringify(item.snapshot.draft)) as Editable;tagText.value=item.snapshot.tagText;sourceText.value=item.snapshot.sourceText;applying=false;recovery.value=[];paused.value=true;staleRecovery.value=item.baseVersion!==baseVersion;changed();if(persistLocal()){try{if(!removeCapturedRecovery(localStorage,item))localIssue.value='另一个标签页更新了恢复副本，较新的副本已保留。';}catch{}}saveStatus.value=staleRecovery.value?'本机记录基于较早版本。请先导出并核对服务器内容，再手动保存合并结果。':'已恢复本机修改，请检查后手动保存。'; }
function keepServer() { for(const item of recovery.value){try{if(!removeCapturedRecovery(localStorage,item))localIssue.value='另一个标签页更新了恢复副本，较新的副本已保留。';}catch{}}recovery.value=[];saveStatus.value='已保留服务器草稿。';schedule(); }
function download() { exportDraft(snapshot(),props.collection); }
function restoring(value:boolean){historyRestoring.value=value;emit('restoreBusy',value);if(value){restoreStamp=snapshotString(snapshot());if(timer)clearTimeout(timer);}else schedule();}
function restored(record:DraftRecord<Editable>) {
  emit('restoreBusy',false);
  baseVersion=record.version;
  if(restoreStamp!==snapshotString(snapshot())){baseline=snapshotString({draft:record.draft as unknown as Record<string,unknown>,tagText:'tags' in record.draft?record.draft.tags.join('，'):'',sourceText:'sourceLinks' in record.draft?record.draft.sourceLinks.join('\n'):''});emit('restored',record);dirty.value=snapshotString(snapshot())!==baseline;paused.value=true;emit('dirty',dirty.value);persistLocal();saveStatus.value='历史版本已恢复到服务器；恢复期间产生的新编辑仍保留，请核对后手动保存。';historyOpen.value=false;historyRestoring.value=false;return;}
  applying=true;draft.value=JSON.parse(JSON.stringify(record.draft));tagText.value='tags' in record.draft?record.draft.tags.join('，'):'';sourceText.value='sourceLinks' in record.draft?record.draft.sourceLinks.join('\n'):'';applying=false;baseline=snapshotString(snapshot());dirty.value=false;paused.value=false;staleRecovery.value=false;removeOwnRecovery();emit('dirty',false);emit('restored',record);historyOpen.value=false;historyRestoring.value=false;saveStatus.value='历史内容已恢复为新的草稿。'; }
onBeforeUnmount(()=>{disposed=true;if(timer)clearTimeout(timer);emit('restoreBusy',false);});
function prune(value:unknown):unknown{if(Array.isArray(value))return value.map(prune);if(value&&typeof value==='object'){return Object.fromEntries(Object.entries(value).filter(([key,item])=>!(item===''&&['sourceUrl','filename','coverAssetId','captionsAssetId','aspectRatio'].includes(key))).map(([key,item])=>[key,prune(item)]));}return value;}
function save(publish=false,automatic=false){if(props.busy||historyRestoring.value||!props.authenticated||recovery.value.length||composing.value)return;if(automatic&&(!props.record||paused.value))return;if(staleRecovery.value&&!window.confirm('这份本机恢复内容来自较早版本。已核对并合并服务器的新内容，确认保存当前编辑吗？'))return;if(timer)clearTimeout(timer);issues.value=[];
const payload=JSON.parse(JSON.stringify(draft.value)) as Editable;
if(props.collection==='creations'){const value=payload as CreationDraft;for(const block of value.blocks)if('providerRef' in block&&block.providerRef)block.providerRef.contentId=providerContentId(block.providerRef.provider,block.providerRef.contentId);value.tags=tagText.value.split(/[，,]/).map(tag=>tag.trim()).filter(Boolean);value.sourceLinks=sourceText.value.split('\n').map(url=>url.trim()).filter(Boolean);}
if(props.collection==='playlists')for(const track of (payload as PlaylistDraft).tracks)if(track.providerRef)track.providerRef.contentId=providerContentId(track.providerRef.provider,track.providerRef.contentId);
if(props.collection==='fitness')(payload as FitnessEntryDraft).tags=tagText.value.split(/[，,]/).map(tag=>tag.trim()).filter(Boolean);
const schema={creations:CreationDraftSchema,albums:AlbumDraftSchema,fitness:FitnessEntryDraftSchema,playlists:PlaylistDraftSchema}[props.collection];const parsed=schema.safeParse(prune(payload));if(!parsed.success){issues.value=parsed.error.issues.map(issue=>`${issue.path.join(' · ')}：${issue.message}`);paused.value=true;saveStatus.value='自动保存已暂停，请修正提示后手动保存。';persistLocal();return;}
const sent=snapshotString(snapshot());saveStatus.value=automatic?'正在自动保存草稿…':'正在保存草稿…';
emit('save',parsed.data,publish,(record,error)=>{if(disposed)return;if(!record){paused.value=true;saveStatus.value=error instanceof ApiError&&error.status===409?'版本冲突：当前修改和本机副本已保留，自动保存已暂停。请导出后重新读取并合并。':'保存未完成，自动保存已暂停。本机修改保留，请检查后重试。';persistLocal();return;}
const oldRecovery=recoveryRecord();baseVersion=record.version;entryId=record.id;baseline=sent;dirty.value=acknowledgeSnapshot(sent,snapshotString(snapshot())).dirty;emit('dirty',dirty.value);paused.value=false;staleRecovery.value=false;
pendingRemoval.push(oldRecovery);let localSaved=true;if(dirty.value){localSaved=persistLocal();schedule();}else removeOwnRecovery();saveStatus.value=dirty.value?'上一份草稿已保存，较新的编辑尚未保存。':`草稿已保存 · ${dateTime(record.updatedAt)}`;
if(!localSaved&&oldRecovery.entryId!==entryId)return {entryId:oldRecovery.entryId,tabId:oldRecovery.tabId};
});}
function newId(){return crypto.randomUUID();}
function trackSource(index:number,event:Event){const track=playlist.value.tracks[index];if(!track)return;if((event.target as HTMLSelectElement).value==='asset'){delete track.providerRef;track.assetId='';}else{delete track.assetId;track.providerRef={provider:'netease',contentId:''};}}
function moveTrack(index:number,direction:number){const to=index+direction;if(to<0||to>=playlist.value.tracks.length)return;const moved=playlist.value.tracks.splice(index,1)[0];if(!moved)return;playlist.value.tracks.splice(to,0,moved);playlist.value.tracks.forEach((track,i)=>track.sortOrder=i);}
</script>
<template><form novalidate @submit.prevent="save(false)" @compositionstart="composing=true" @compositionend="composing=false;schedule()"><section v-if="recovery.length" class="notice mb24" aria-label="本机草稿恢复"><h3>发现本机未保存内容</h3><p class="mt8">恢复前不会自动覆盖服务器。每个标签页分别保留副本；请先核对时间和版本。</p><div v-for="item in recovery" :key="item.tabId" class="flex between mt16"><span>{{dateTime(new Date(item.updatedAt).toISOString())}} · 基于版本 {{item.baseVersion}}</span><div class="flex"><button type="button" @click="exportDraft(item.snapshot,collection)">导出副本</button><button type="button" @click="restoreLocal(item)">恢复到编辑器</button></div></div><button type="button" class="mt16" @click="keepServer">保留服务器内容并清除这些副本</button></section><p v-if="localIssue" class="notice error mb16" role="alert">{{localIssue}}</p><p class="hint mb16" role="status">{{saveStatus || (record?'停止编辑 30 秒后自动保存草稿，发布需另行确认。':'新内容先保存在本机；首次点击保存草稿后开启自动保存。')}} <span v-if="paused">自动保存已暂停。</span></p><fieldset :disabled="busy||historyRestoring||recovery.length>0" :inert="historyRestoring||recovery.length>0" class="editor-fieldset"><div class="editor-actions"><span class="hint">{{ record?`已保存版本 ${record.version}`:'尚未保存' }} · 信息未填完也可保存，发布前再补齐</span><div class="flex"><button type="button" @click="emit('cancel')">返回列表</button><button type="button" @click="previewOpen=true">预览内容</button><button type="button" @click="download">导出草稿</button><button v-if="record" type="button" @click="historyOpen=!historyOpen">草稿历史</button><button type="submit">{{busy?'正在保存…':'保存草稿'}}</button><button type="button" class="primary" @click="save(true)">保存并准备发布</button></div></div><div v-if="issues.length" class="notice error mt16" role="alert"><strong>请先完善这些信息</strong><ul><li v-for="issue in issues" :key="issue">{{issue}}</li></ul></div>
<div v-if="collection==='creations'" class="editor-workspace"><div><label class="field">创作标题<input v-model="creation.title" class="editor-title" maxlength="120" placeholder="为这条创作起个名字"></label><label class="field mt16">摘要<textarea v-model="creation.summary" maxlength="300" rows="3" placeholder="用一两句话介绍这条创作"></textarea></label><div class="mt32"><BlockEditor v-model="creation.blocks"/></div></div><aside class="panel props"><h2>创作资料</h2><label class="field mt24">内容类型<select v-model="creation.kind"><option value="mixed">混合创作</option><option value="article">文章</option><option value="project">项目 / 作品</option></select></label><label class="field">链接名称<input v-model="creation.slug" placeholder="my-creation" maxlength="160"><small class="hint">/creations/{{creation.slug||'链接名称'}}</small></label><label class="field">标签<input v-model="tagText" placeholder="用逗号分隔，最多20个"></label><AssetField v-model="creation.coverAssetId" label="封面，可选" kind="image" optional/><label class="check mt24"><input v-model="creation.featured" type="checkbox">首页精选</label><label class="field mt16">排序<input v-model.number="creation.sortOrder" type="number" min="0" step="1"></label><details class="mt24"><summary>搜索与来源</summary><label class="field mt16">搜索标题<input v-model="creation.seo.title" maxlength="120"></label><label class="field">搜索描述<textarea v-model="creation.seo.description" maxlength="300"></textarea></label><label class="field">来源链接，每行一个<textarea v-model="sourceText" placeholder="https://" rows="4"></textarea></label></details></aside></div>
<div v-else-if="collection==='albums'" class="editor-workspace"><div class="stack"><div class="panel"><label class="field">摄影系列标题<input v-model="album.title" class="editor-title" maxlength="120"></label><label class="field">系列介绍<textarea v-model="album.description" rows="5" maxlength="5000"></textarea></label></div><PhotoEditor v-model="album.photos" :limit="500" location-enabled/></div><aside class="panel props"><h2>系列资料</h2><label class="field mt24">链接名称<input v-model="album.slug" maxlength="160"></label><AssetField v-model="album.coverAssetId" label="系列封面" kind="image" optional/><label class="check mt24"><input v-model="album.featured" type="checkbox">首页精选</label><label class="field mt16">排序<input v-model.number="album.sortOrder" type="number" min="0" step="1"></label></aside></div>
<div v-else-if="collection==='fitness'" class="editor-workspace"><div class="stack"><div class="panel"><label class="field">记录标题<input v-model="fitness.title" class="editor-title" maxlength="120"></label><label class="field">记录说明<textarea v-model="fitness.caption" rows="4" maxlength="2000"></textarea></label></div><PhotoEditor v-model="fitness.photos"/></div><aside class="panel props"><h2>记录资料</h2><label class="field mt24">标签<input v-model="tagText" placeholder="用逗号分隔"></label><label class="field mt24">记录归属日期<input v-model="fitness.entryDate" type="date" required></label><p class="hint mt16">这是本条记录的日期；每张照片可单独填写拍摄日期，不影响坚持天数。</p><label class="field mt16">排序<input v-model.number="fitness.sortOrder" type="number" min="0" step="1"></label><label class="check mt24"><input v-model="fitness.featured" type="checkbox">首页精选</label></aside></div>
<div v-else class="editor-workspace"><div><div class="panel"><label class="field">歌单名称<input v-model="playlist.name" class="editor-title" maxlength="120" required></label><div class="form-grid mt16"><label class="field">歌单来源<select v-model="playlist.source" @change="playlist.sourceId=playlist.source==='local'?null:''"><option value="local">本站歌单</option><option value="netease">网易云音乐</option><option value="tencent">QQ 音乐</option></select></label><label v-if="playlist.source!=='local'" class="field">原平台歌单 ID<input v-model="playlist.sourceId" maxlength="200" required></label></div><p class="hint mt16">这里只管理本站呈现，不修改外部平台账号或歌单。</p></div><div class="flex between mt32"><h2>曲目与顺序</h2><button type="button" :disabled="playlist.tracks.length>=500" @click="playlist.tracks.push({id:newId(),title:'',artist:'',assetId:'',coverAssetId:null,sortOrder:playlist.tracks.length})">＋ 添加曲目</button></div><div v-if="!playlist.tracks.length" class="empty mt16"><p>还没有添加曲目。</p></div><article v-for="(track,index) in playlist.tracks" :key="track.id" class="content-block mt16"><header class="block-head"><strong>曲目 {{index+1}}</strong><div class="flex row-actions"><button type="button" :disabled="index===0" aria-label="曲目前移" @click="moveTrack(index,-1)">↑</button><button type="button" :disabled="index===playlist.tracks.length-1" aria-label="曲目后移" @click="moveTrack(index,1)">↓</button><button type="button" class="danger" @click="playlist.tracks.splice(index,1);playlist.tracks.forEach((row,i)=>row.sortOrder=i)">移除</button></div></header><div class="block-body"><div class="form-grid"><label class="field">曲名<input v-model="track.title" maxlength="120" required></label><label class="field">艺术家<input v-model="track.artist" maxlength="120"></label><label class="field">曲目来源<select :value="track.providerRef?'provider':'asset'" @change="trackSource(index,$event)"><option value="asset">本站音频</option><option value="provider">外部音乐</option></select></label><template v-if="track.providerRef"><label class="field">音乐平台<select v-model="track.providerRef.provider"><option value="netease">网易云音乐</option><option value="tencent">QQ 音乐</option></select></label><label class="field">歌曲 ID<input v-model="track.providerRef.contentId" maxlength="200" required></label></template></div><a v-if="externalMediaLink(track.providerRef)" class="button mt16" :href="externalMediaLink(track.providerRef)" target="_blank" rel="noopener noreferrer">到原平台试听 ↗</a><AssetField v-if="!track.providerRef" :model-value="track.assetId" label="音频文件" kind="audio" @update:model-value="value=>track.assetId=value??undefined"/><AssetField v-model="track.coverAssetId" label="曲目封面" kind="image" optional/></div></article></div><aside class="panel props"><h2>播放设置</h2><label class="check mt24"><input v-model="playlist.enabled" type="checkbox">启用歌单</label><label class="check mt16"><input v-model="playlist.isDefault" type="checkbox">作为首页默认歌单</label><label class="field mt24">排序<input v-model.number="playlist.sortOrder" type="number" min="0" step="1"></label><p class="hint mt24">访客点击才播放。首页音乐与站内音视频共享播放控制。</p></aside></div>
</fieldset><RevisionHistory v-if="historyOpen&&record" :collection="collection" :record="record" :disabled="dirty||busy||recovery.length>0" @restored="restored" @restoring="restoring" @close="historyOpen=false"/><DraftPreview v-if="previewOpen" :collection="collection" :draft="draft" @close="previewOpen=false"/></form></template>
<style scoped>.editor-actions>.flex{flex-wrap:wrap;justify-content:flex-end}.editor-actions>.flex button{white-space:nowrap}@media(max-width:600px){.editor-actions>.flex{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));width:100%}.editor-actions>.flex button{width:100%}}</style>
